/** Single GM-confirmed campaign clock; rounds and IR remain strictly encounter-local. */
function confirmCalendarWoundDay(characterId,woundId,daySinceInjury){
 const clock=data.campaignClock;
 if(!clock)return; // Legacy installation remains operable before calendar initialization.
 const elapsed=elapsedCalendarDays(clock,'wound',characterId,woundId);
 if(elapsed===null)throw Error('Kalendář: tato historická rána nemá potvrzený den vzniku. Nejprve ji ukotvěte v Kalendáři.');
 if(!Number.isSafeInteger(daySinceInjury)||daySinceInjury!==elapsed)
  throw Error('Kalendář: dny od vzniku rány jsou '+elapsed+'; formulář uvádí '+daySinceInjury+'. Před hodem aktualizujte čas.');
}
function confirmCalendarElapsed(characterId,kind,ageMinutes){
 if(!data.campaignClock)return;
 const a=getCampaignAnchor(data.campaignClock,kind,characterId);
 if(!a)throw Error('Kalendář: chybí doložený okamžik '+kind+'. Potvrďte jej na kartě Kalendář.');
 if(data.campaignClock.minute-a.minute<ageMinutes)
  throw Error('Kalendář: '+kind+' dosud nemá uplynulý požadovaný čas.');
}
function logCalendarCombatResolution(c,state,kind){
 if(!data.campaignClock)return;
 const sourceEventId=state.events?.at(-1)?.id;
 if(!sourceEventId||!state.events.some(e=>e.id===sourceEventId))throw Error('Kalendář: chybí fyzicky potvrzená zdrojová Combat událost');
 data.campaignClock=recordCampaignResolution(data.campaignClock,{eventId:uuid(),sourceEventId,
  characterId:c.id,kind});
}
function autoAnchorNewCombatOrigins(c,before,after,eventId){
 if(!data.campaignClock)return;
 const previous=new Set((before?.wounds??[]).map(w=>w.id));
 for(const w of after.wounds??[]){
  if(!previous.has(w.id)&&!getCampaignAnchor(data.campaignClock,'wound',c.id,w.id))
   data.campaignClock=anchorCampaignOrigin(data.campaignClock,{kind:'wound',characterId:c.id,woundId:w.id,
    eventId:uuid(),combatEventId:eventId,source:'confirmed-combat'});
 }
 for(const [kind,started] of [['extended-shock',!before?.extendedShock&&!!after.extendedShock],
  ['coma',!before?.coma?.active&&!!after.coma?.active],
  ['blood-loss',!(before?.bloodLoss?.bp>0)&&(after.bloodLoss?.bp>0)]]){
  if(started)
   data.campaignClock=anchorCampaignOrigin(data.campaignClock,{kind,characterId:c.id,eventId:uuid(),combatEventId:eventId,source:'confirmed-combat'});
 }
}
function refreshCalendarHealingFields(form){
 if(!data.campaignClock||!form)return;
 const woundField=form.querySelector('select[name="wound"]');
 if(woundField){
  const [id,woundId]=woundField.value.split('::');
  const days=elapsedCalendarDays(data.campaignClock,'wound',id,woundId);
  const field=form.querySelector('input[name="daySinceInjury"]');
  if(field)field.value=days===null?'':String(days);
  for(const f of form.querySelectorAll('input[name^="resumeDay:"]')){
   const other=f.name.slice('resumeDay:'.length);
   const otherDays=elapsedCalendarDays(data.campaignClock,'wound',id,other);
   f.value=otherDays===null?'':String(otherDays);
  }
 }
 const target=form.querySelector('select[name="targetId"]');
 if(form.id==='hmk-blood-regeneration-form'&&target){
  const days=elapsedCalendarDays(data.campaignClock,'blood-loss',target.value);
  const field=form.querySelector('input[name="daySinceBloodLoss"]');
  if(field)field.value=days===null?'':String(days);
 }
}
function refreshAllCalendarHealingFields(){
 if(!data.campaignClock)return;
 for(const f of document.querySelectorAll('#hmk-treatment-form,#hmk-healing-roll-form,#hmk-infection-course-form,#hmk-grim-shock-form,#hmk-blood-regeneration-form'))
  refreshCalendarHealingFields(f);
}
