// The current creation character is a persisted CHARACTER, never a second draft.
const CREATION_LAST_ID='hmk-ledger-last-creation-character-v1';
function creationDrafts(){return data.characters.filter(c=>c.hmk?.creation&&!['complete','auto-generated'].includes(c.hmk.creation.status))}
function resumeCreation(id){
 const c=character(id);if(!c?.hmk?.creation)return false;
 if(combatInitiativeSequence)return false;
 selected=id;view='creation';overlay=null;
 try{sessionStorage.setItem(CREATION_LAST_ID,id)}catch{}
 render();return true;
}
let automaticGenerationBusy=false;
const automaticGenerationDebug=false;
/** One click, with no user intervention, drives the real persisted 14-step
 * creation flow and the same validation as the manual wizard. Failed
 * candidates are deleted from storage; never expose a half-generated draft.
 */
async function generateCharacterFullyAutomatically(mode='random',traitProfile='random',preferences={}){
 if(automaticGenerationBusy||storageReadOnly||combatInitiativeSequence)return;
 automaticGenerationBusy=true;
 const originalView=view,originalSelected=selected;
 let finalError='';
 try{
  // Privacy-preserving, deterministic local interpretation; no network/API.
  const interpreted=interpretCharacterDescription(preferences.description,preferences.traits);
  const generatorProfile=mode==='traits'?(Object.hasOwn(AUTO_TRAIT_PROFILES,traitProfile)&&traitProfile!=='random'?traitProfile:interpreted.primary):'random';
  const generationPreferences=mode==='traits'?{...preferences,semantic:interpreted,semanticRanking:interpreted.ranking}:{};
  const wanted=mode==='traits'?String(preferences.occupation||'').trim():'';
  const plan=wanted?chooseOccupationTarget(wanted,preferences.folk||''):null;
  if(plan)generationPreferences.targetPlan=plan;
  if(mode==='traits'){overlay=null;render();}
  for(let attempt=1;attempt<=(plan?24:12);attempt++){
   const id=uuid(),name=`${generatorProfile==='random'?'Náhodná postava':AUTO_TRAIT_PROFILES[generatorProfile].label} ${new Date().toLocaleDateString('cs-CZ')} · ${attempt}`;
   if(!mutate(()=>data.characters.push({id,name,kind:'PC',occupation:'',description:'',portrait:'',hmk:{creation:defaultCreation(),skills:[],injuries:[],attributes:{}}})))throw Error('Nelze bezpečně založit profil v úložišti');
   selected=id;view='creation';render();
   const rejected=new Map();let ticks=0;
   try{
    while(ticks++<170){
     const target=character(id);if(!target)throw Error('Ztracen vytvořený profil');
     if(target.hmk?.creation?.status==='review-required'){
      if(!mutate(()=>{const t=character(id);const kit=prepareStartingKit(t,allCatalogItems(),uuid);if(data.inventory.some(x=>x.characterId===id))throw Error('Generátor nesmí nahradit existující inventář');data.inventory.push(...kit.items);labelAutoGeneratedProof(t,{profile:generatorProfile,attempt});if(plan)t.hmk.creation.values.autoTargetPlan={occupation:plan.occupation,folk:plan.folk,region:plan.region,realm:plan.realm,parentClass:plan.socialClass,classMode:"software d20 candidate trials",regionMode:"explicit HMK p.24 selection",discardedClassRolls:plan.rejectedClassRolls.slice(),discardedTribeRolls:(plan.rejectedTribeRolls||[]).slice(),discardedParentRolls:plan.rejectedParentRolls.slice(),discardedRegionRolls:plan.rejectedRegionRolls.slice(),discardedTalentTrials:plan.rejectedTalentTrials};t.hmk.creation.values.autoGeneration.preferences={folk:generationPreferences.folk||'',occupation:generationPreferences.occupation||'',traits:interpreted.traits,description:interpreted.description};t.hmk.creation.values.autoGeneration.semantic=mode==='traits'?{engine:interpreted.engine||'deterministic-czech-offline-v3',primary:interpreted.primary,ranking:interpreted.ranking,confidence:interpreted.confidence,occupationCandidates:interpreted.occupationCandidates,skillPreferences:interpreted.skillPreferences,folkPreference:interpreted.folkPreference,agePreference:interpreted.agePreference,narrativeTraits:interpreted.narrativeTraits,attributeAspirations:interpreted.attributeAspirations,moralityPreference:interpreted.moralityPreference,evidence:interpreted.evidence,disclaimer:interpreted.disclaimer,summary:interpreted.summary||'',uncertainties:interpreted.uncertainties||interpreted.contradictions||[]}:null;t.hmk.creation.values.autoStartingKit={...kit.summary,source:'HMK p.51 + tištěný katalog pp.99–121; pravidlově omezená návrhová výbava, ne pevný příděl'};if(mode==='traits'){const sem=t.hmk.creation.values.autoGeneration.semantic;sem.realizedOccupation=t.hmk.occupation||t.occupation||'';sem.unfulfilledOccupation=sem.occupationCandidates.length>0&&!sem.occupationCandidates.some(o=>sem.realizedOccupation===o||sem.realizedOccupation.startsWith(o+' ('));sem.realizedFolk=t.hmk.folk;sem.unfulfilledFolk=Boolean(sem.folkPreference&&sem.realizedFolk!==sem.folkPreference);sem.realizedAgeGroup=t.hmk.ageGroup;sem.unfulfilledAge=Boolean(sem.agePreference&&sem.realizedAgeGroup!==sem.agePreference);}t.hmk.creation.status='auto-generated';t.hmk.creation.reviewRequired=false;t.description=`Plně automatická tvorba · ${AUTO_TRAIT_PROFILES[generatorProfile].label}. Hody byly vygenerovány softwarem; nikoli fyzicky. Počáteční vybavení: ${kit.summary.itemCount} položek, ${kit.summary.costPence}d z limitu ${kit.summary.budgetPence}d. Hotovost: ${kit.summary.startingCoinsPence}d (nezávislá na limitu vybavení).${interpreted.description?' Charakter: '+interpreted.description:''}`;if(mode==='traits'){const sem=t.hmk.creation.values.autoGeneration.semantic;const cautions=[];if(sem.unfulfilledOccupation)cautions.push('profese z popisu nebyla podle pravidel dostupná');if(sem.unfulfilledFolk)cautions.push('Folk neodpovídá záměru');if(sem.unfulfilledAge)cautions.push('věk z popisu není pro tento Folk povolen');if(cautions.length)t.description+=' POZOR: '+cautions.join('; ')+'.';}}))throw Error('Nelze uložit důkaz automatického generování a počátečního vybavení');
      selected=id;view='sheet';render();return true;
     }
     const stage=target.hmk.creation.step===12?target.hmk.creation.skillStage:-1;
     const key=`${target.hmk.creation.step}:${stage}`;
     const form=document.getElementById('creation-step-form');if(!form)throw Error('Průvodce nevykreslil aktivní formulář');
     const before=JSON.stringify(target.hmk.creation);
     const action=prepareAutomaticStep(form,target,{profile:generatorProfile,die:secureAutoDie,rejected:[...(rejected.get(key)??[])],preferences:generationPreferences});
     const lastSkill=action==='skill'?form.elements.namedItem('skillName')?.value:null;
     if(automaticGenerationDebug&&target.hmk.creation.step===12&&stage===0)console.warn('FOLK STAGE FORM',JSON.stringify(Object.fromEntries(new FormData(form))),target.hmk.pantheon);
     if(automaticGenerationDebug&&target.hmk.creation.step===12&&[2,3,5,6,7].includes(stage)&&action==='next')console.warn('SKILL STAGE FORCED NEXT',stage,JSON.stringify(target.hmk.creation.skillDP),Array.from(form.querySelectorAll('select[name="skillName"] option')).map(x=>x.value),[...(rejected.get(key)||[])]);
     const btn=form.querySelector(`button[name="action"][value="${action}"]`);
     if(!btn)throw Error(`Chybí potvrzovací prvek pro krok ${key}: ${action}`);
     if(!form.checkValidity()){
      const bad=[...form.elements].filter(e=>!e.checkValidity?.()).map(e=>e.name).filter(Boolean);
      throw Error(`Nevyplněné povinné údaje ${key}: ${bad.join(', ')}`);
     }
     btn.click();
     const after=character(id)?.hmk?.creation;
     if(!after)throw Error('Postava se po kroku ztratila');
     if(JSON.stringify(after)===before){
      if(action==='skill'&&lastSkill){if(!rejected.has(key))rejected.set(key,new Set());rejected.get(key).add(lastSkill);continue;}
      throw Error(`Validace nepovolila ${key}, akce ${action}`);
     }
     if(after.step!==target.hmk.creation.step||after.skillStage!==stage)rejected.clear();
     if(ticks%2===0)await new Promise(resolve=>setTimeout(resolve,0));
    }
    throw Error('Generátor překročil limit pravidlových kroků');
   }catch(err){finalError=String(err.message||err);if(automaticGenerationDebug)console.warn('Autogenerátor, neúspěšný pokus',attempt,finalError,character(id)?.hmk?.creation?.step,character(id)?.hmk?.creation?.skillStage,character(id)?.hmk?.folk,character(id)?.hmk?.familyOccupation);}
   // Rollback only the character created in this attempt; the ordinary
   // protected CAS guard still runs and must succeed before retrying.
   const removed=mutate(()=>{data.characters=data.characters.filter(c=>c.id!==id);data.inventory=data.inventory.filter(x=>x.characterId!==id);data.journal=data.journal.filter(x=>x.characterId!==id)});
   if(!removed)throw Error('Automatická tvorba selhala a nepodařilo se bezpečně vrátit dílčí profil');
   selected=originalSelected;view='characters';render();
  }
  throw Error('Po '+(plan?24:12)+' interních pokusech nebylo možné dokončit postavu podle doložených pravidel. Poslední příčina: '+finalError);
 }catch(err){selected=originalSelected;view=originalView;render();alert('Automatický generátor: '+err.message);return false}
 finally{automaticGenerationBusy=false;}
}
// A character-specific action belongs exclusively to that character card;
// never infer the target from the last selected or first available draft.
function creationCardAction(c){
 if(!c.hmk?.creation)return '';
 const status=c.hmk.creation.status;
 const label=status==='review-required'?'GM kontrola tvorby':status==='complete'||status==='auto-generated'?'Upravit tvorbu':'Pokračovat v tvorbě';
 const progress=status==='in-progress'?` · krok ${esc(c.hmk.creation.step)}/14`:'';
 return `<button type="button" class="secondary" data-resume-creation="${esc(c.id)}" aria-label="${esc(label+' postavy '+c.name+progress)}">${esc(label)}</button>`;
}
