function libraryCharacterOptions(){const preferred=libraryRecipientId||selected||data.characters[0]?.id;return data.characters.map(c=>{const cash=coinBalance(c);return `<option value="${esc(c.id)}" ${c.id===preferred?'selected':''}>${esc(c.name)}${c.occupation?' · '+esc(c.occupation):''} · ${cash.ok?esc(cash.balance)+'d':'hotovost nedoložena'}</option>`}).join('')}
function libraryAssignForm(itemId,kind='item',available=true,offer=null){
 if(!data.characters.length)return '<span class="library-warning">Nejdříve vytvořte postavu.</span>';
 if(!available)return '<span class="library-warning">Přiřazení není doložené katalogem.</span>';
 const preferred=character(libraryRecipientId||selected||data.characters[0]?.id)||data.characters[0];
 const cash=coinBalance(preferred),price=offer?.pricePence??null,canBuy=price!==null&&cash.ok&&cash.balance>=price;
 const reason=price===null?'Nákup nedostupný: chybí jednoznačná cena v d.':!cash.ok?cash.reason:cash.balance<price?`Nedostatek hotovosti (${cash.balance}d).`:'';
 return `<form class="library-assign" data-library-form="${esc(kind)}"><input type="hidden" name="itemId" value="${esc(itemId)}"><select name="recipientId" aria-label="Postava pro převzetí nebo nákup" required>${libraryCharacterOptions()}</select><div class="library-acquire-actions"><button type="submit" name="acquisition" value="buy" ${canBuy?'':`disabled title="${esc(reason)}"`}>Koupit${price!==null?' '+(offer.quantity>1?esc(offer.quantity)+' ks · ':'· ')+esc(price)+'d':''}</button><button type="submit" name="acquisition" value="free" class="secondary">Vzít zdarma</button></div>${reason?`<small class="library-purchase-hint">${esc(reason)}</small>`:''}</form>`;
}
function libraryBrief(i){
 const p=i.properties||{},numeric=v=>v===null||v===undefined||v===''?'—':esc(v);
 const impact=m=>m?`${esc(m.impactDie??'—')}${Number.isFinite(m.impactModifier)?(m.impactModifier>=0?'+':'')+m.impactModifier:''}${m.aspect?' '+esc(m.aspect):''}`:'—';
 const firstMode=Array.isArray(p.verifiedModes)?p.verifiedModes[0]:null;
 const armourValue=Object.values(p.locationProtection||{})[0];
 const summary=armourValue?`b${numeric(armourValue.b)} e${numeric(armourValue.e)} p${numeric(armourValue.p)} f${numeric(armourValue.f)}`:'—';
 const price=p.pricePence!==undefined?`${numeric(p.pricePence)} d`:p.pricePerDozenPence!==undefined?`${numeric(p.pricePerDozenPence)} d/12`:'—';
 const weight=p.weightLb!==undefined?`${numeric(p.weightLb)} lb`:'—';
 if(i.category==='armor')return [esc(p.material||'—'),`ENC ${numeric(p.encumbrance)}${p.printedEncCode==='a'?' (podmíněné)':p.printedEncCode==='p'?' (PER)':''}`,summary,price,weight];
 if(i.category==='shield')return [`WQ ${numeric(p.quality)}`,`Block ${numeric(p.shieldModifier??p.blockModifier)}`,`Deflect ${numeric(p.deflect)}`,price,weight];
 if(i.category==='weapon')return [`WQ ${numeric(p.quality)}`,p.baseRangeFt!==undefined?`BR ${numeric(p.baseRangeFt)} ft`:`HFT ${numeric(p.heft)} · LNG ${numeric(p.length)}`,impact(firstMode),price,weight];
 if(p.projectileKind)return [esc(p.projectileKind),esc(p.shaftWeight||p.slingProjectileForm||'—'),esc(p.impactDie||'—'),price,weight];
 return [esc(i.category),esc(p.skill||p.use||'—'),esc(p.quality||'—'),price,weight];
}
