  throw Error('Poloha pádu je přípustná pouze po neúspěšném Stumble');
 const pattern=/^\s*-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?\s*$/;
 if(!pattern.test(String(v.fallPosition??'')))throw Error('GM musí zadat konkrétní souřadnice pádu x,y');
