// HMK p.60–62 Skill Workbench: read from the authoritative character, append one journal proof.
function skillActorMastery(actor,name){const row=availableMasteries(actor).find(x=>x.name===name);if(!row)throw Error('Zvolená dovednost nemá ověřené ML: '+name);return row;}
function skillAssistantMLs(form,primaryName){
 const ids=Array.from({length:4},(_,i)=>form.elements.namedItem('assist'+(i+1))?.value||'').filter(Boolean);
 if(new Set(ids).size!==ids.length)throw Error('Stejný pomocník je uveden vícekrát');
 return ids.map(id=>{const other=character(id);if(!other||id===selected)throw Error('Neplatný pomocník');return {actor:other,mastery:skillActorMastery(other,primaryName)}});
}
// Shared Skill Workbench v93.269. One primary d100 for each participant.
// All evidenced modifiers remain visible; GM may only adjudicate unresolved
// armour fields with an explicit checkbox, preserved in immutable journal.
function skillAutoFor(actor,name,form=null,prefix='A'){
 const seq=liveInitiativeSequence();
 const field=k=>form?.elements.namedItem(k+prefix);
 const value=k=>{const s=field(k)?.value?.trim();return s===''||s==null?null:s;};
 const ctx=automaticSkillContext({actor,inventory:data.inventory,name,
  combatRound:seq?.round??null,combatTimelineId:seq?.timelineId??null,
  gearPolicy:field('gearConfirmed')?.checked?'gm':'advisory',
  manualENC:value('gmENC'),manualBulk:value('gmBulk'),manualPerception:value('gmPer'),
  sensoryBasis:value('sensoryBasis'),blindnessDecision:value('blindnessDecision'),visionBasis:value('visionBasis')});
 const shamanBoost=activeShamanSkillModifier({actor,skill:name,minute:data.campaignClock?.minute,inventory:data.inventory});
 if(shamanBoost){ctx.condition.modifier+=shamanBoost;ctx.modifier+=shamanBoost;
  ctx.breakdown.push({label:'Ancestor Rite/Talisman · overlapping MB',value:shamanBoost,source:'confirmed-shaman-rite-talisman-p302'});}
 const bonus=activeDoctrineModifier(actor,name,data.campaignClock?.minute);
 if(bonus){ctx.condition.modifier+=bonus;ctx.modifier+=bonus;
  ctx.breakdown.push({label:'Doctrine Blessing',value:bonus,source:'confirmed-ceremony-p316'});}
 return ctx;
}
function skillTraumaText(tr){return 'Shock '+tr.shock.value+', Injury '+tr.injury.modifier+', Bulk '+tr.bulk.modifier+', PER '+tr.perception.modifier+(tr.slPenalty?' · STN: −'+tr.slPenalty+' SL':'');}
function skillConditionsText(ctx){return 'Fatigue '+ctx.fatigue.modifier+' ('+ctx.fatigue.source+'), ENC '+ctx.enc.modifier+' ('+ctx.enc.source+')';}
function skillResolvedResult({mastery,form,dieKey,gmModifier=0,condition,trauma,secondaryMLs=[],assistants=[],svExtra=0,exceptional=false}){
 if(condition?.deafnessForcedCF){
  if(form.elements.namedItem(dieKey)?.value?.trim())throw Error('Hluchota (p184): sluchový PER/Awareness test je automatický CF; žádný d100 se nehází.');
  return {result:automaticCriticalFailure({ml:mastery.ml,reason:'HMK p.184 – hluchota, sluchový test je automatické CF',svExtra}),die:{roll:null,origin:'rule-forced-deafness'}};
 }
 if(trauma?.injury?.forcedCF){
  if(form.elements.namedItem(dieKey)?.value?.trim())throw Error('Grievous: automatické CF nepřijímá ručně zadaný d100');
  return {result:automaticCriticalFailure({ml:mastery.ml,reason:'HMK p.170 – nepoužitelná zóna',woundIds:trauma.injury.unusableWoundIds,svExtra}),die:{roll:null,origin:'rule-forced-no-die'}};
 }
 const die=skillDie(form,dieKey,100);
 return {die,result:adjustSkillResultForTrauma(resolveSkillTest({ml:mastery.ml,roll:die.roll,gmModifier:gmModifier+condition.modifier+trauma.modifier,secondaryMLs,assistants,svExtra,exceptional}),trauma)};
}
function skillConsequenceText(x){return x.type==='none'?'Žádný zvláštní následek':x.type==='combat-handoff'?'Combat Mishap: '+x.mishap+'; předat do existujícího Combat průvodce':x.reason;}
function skillPendingText(p){return p?.events?.length?'\nNevyřešené existující Combat události: '+p.events.map(e=>e.type+' ['+e.id+']').join(', '):'';}
function skillDie(form,key,sides){const str=form.elements.namedItem(key)?.value?.trim()??'';if(str==='')return {roll:secureAutoDie(sides),origin:'software'};
 const roll=Number(str);if(!Number.isSafeInteger(roll)||roll<1||roll>sides)throw Error('Hod d'+sides+' musí být celé číslo od 1 do '+sides);
 return {roll,origin:'manually-entered'};
}
function hskVerdictMetric(label,value,extra=''){
 return '<span class="hsk-verdict-chip"><small>'+esc(label)+'</small><strong>'+esc(value==null?'—':value)+'</strong>'+(extra?'<small>'+esc(extra)+'</small>':'')+'</span>';
}
function hskVerdictSide(label,who,result,sr,range=null){
 if(!result)return '';
 return '<section class="hsk-verdict-section"><h4>'+esc(label+' · '+(who||'Postava'))+'</h4><div class="hsk-verdict-grid">'+
 hskVerdictMetric('Primary ML',result.ml)+hskVerdictMetric('EML',range?range.low+'–'+range.high:result.eml,range?'rozsah možného ENC; nikoli potvrzený výsledek':'')+
 hskVerdictMetric('d100',result.roll??'CF bez hodu')+hskVerdictMetric('Success Level',result.level)+
 (sr?hskVerdictMetric('Secondary d10',sr.roll===null?'bez hodu':sr.roll,sr.name):'')+
 (sr?hskVerdictMetric('TN / SR',sr.tn+' / '+(sr.success?'S':'F'),'HMK str. '+sr.sourcePage):'')+'</div>'+
 (sr?'<p class="hsk-verdict-footnote">'+esc(sr.effect||'')+'</p>':'')+'</section>';
}
function hskResultRichHTML(proof,body){
 if(!proof)return '<p>'+esc(body)+'</p>';
 if(proof.type==='special-secondary-roll')return '<section class="hsk-verdict"><h3>'+esc(proof.routineName)+'</h3><div class="hsk-verdict-grid">'+
  hskVerdictMetric('Zdroj HMK','str. '+proof.page)+hskVerdictMetric('Secondary TN',proof.outcome.tn)+
  hskVerdictMetric('Úspěšné SR',proof.outcome.successes+'/'+proof.outcome.rolls.length)+
  hskVerdictMetric('Hody d10',proof.outcome.rolls.join(', ')||'—')+
  (proof.outcome.kind==='fatigue'?hskVerdictMetric('Nová únava','+'+proof.outcome.accrual,'z původních '+proof.outcome.base):'')+
  (proof.outcome.kind==='recovery'?hskVerdictMetric('Obnovená weariness','−'+proof.outcome.wearinessRecovered):'')+
  (proof.outcome.kind==='divine'?hskVerdictMetric(proof.outcome.benedictionModifier===null?'Renewed Faith':'Benediction modifier',proof.outcome.benedictionModifier===null?(proof.outcome.renewedFaith?'+1 maximální Piety':'nepřidáno'):'+'+proof.outcome.benedictionModifier):'')+
  '</div><p class="hsk-verdict-footnote">'+esc(proof.explanation)+'</p></section>';

 const type=proof.type;
 const actor=character(proof.actorId),opponent=proof.opponentId?character(proof.opponentId):null;
 const a=proof.a||proof.result,b=proof.b||null,comparison=proof.comparison||null;
 let html='<div class="hsk-verdict"><h3>Výsledek Skill Testu</h3>';
 if(type==='opposed-tiebreak'){
  const winner=character(proof.winnerId);html+='<section class="hsk-verdict-section"><h4>Rozstřel</h4><div class="hsk-verdict-grid">'+
   hskVerdictMetric('Vítěz',winner?.name||'—')+hskVerdictMetric('Victory Stars','1 ★')+
   hskVerdictMetric('Rozhodující kritérium',proof.method==='higher-d100'?'Vyšší d100':proof.method==='higher-ml'?'Vyšší ML':'Rozhodující d10')+'</div></section>';
 }else{
  html+=hskVerdictSide('Aktivní strana',actor?.name,a,proof.secondaryRollResult,proof.emlRangeA);
  if(b)html+=hskVerdictSide('Protistrana',opponent?.name,b,proof.secondaryRollResultB,proof.emlRangeB);
  let winner='—',stars=0,summary='';
  if(comparison){winner=comparison.winner==='a'?actor?.name:comparison.winner==='b'?opponent?.name:comparison.bothFailed?'Nikdo (oba neuspěli)':'Remíza';stars=comparison.stars||0;
   summary=comparison.tie?'Rozstřel lze použít jen při shodném S/S nebo CS/CS, pokud je potřeba rozhodnout vítěze.':'';}
  else if(type==='assistance-success-test'){winner=a?.level||'—';stars=a?.unopposedStars||0;summary='Bonus pomocníků se započítává do EML (nejvýše +10).';}
  else if(type.includes('value')){winner=a?.level||'—';stars=a?.svTier?.stars||0;summary='SV '+(a?.sv??'—')+' · '+(a?.svTier?.label||'');}
  else{winner=a?.level||'—';stars=a?.unopposedStars||0;}
  html+='<section class="hsk-verdict-section hsk-verdict-final"><h4>Konečný verdikt</h4><div class="hsk-verdict-grid">'+
  hskVerdictMetric(comparison?'Vítěz':'Výsledek',winner||'—')+
  hskVerdictMetric(type.includes('value')?'SV hvězdy':'Victory Stars',stars+' '+(stars?'★'.repeat(Math.min(5,stars)):'—'))+
  (type.includes('value')?hskVerdictMetric('Success Value',a?.sv??'—'):hskVerdictMetric('Úroveň úspěchu',a?.level||'—'))+
  (proof.preliminaryArmour?hskVerdictMetric('Zbrojní výpočet','Předběžný'):'' )+'</div>'+
  (summary?'<p class="hsk-verdict-footnote">'+esc(summary)+'</p>':'')+'</section>';
 }
 if(proof.gmNarrative)html+='<section class="hsk-verdict-section hsk-verdict-narrative"><h4>Vyprávění pro GM</h4><p>'+esc(proof.gmNarrative)+'</p></section>';
 return html+'</div>';
}
function hskCriticalNextHTML(originalId,proof){
 if(!originalId||!proof||proof.type==='critical-followup')return '';
 const sides=proof.a?[{id:proof.actorId,skill:proof.skills?.[0],result:proof.a,side:'A'},...(proof.b?[{id:proof.opponentId,skill:proof.skills?.[1],result:proof.b,side:'B'}]:[])]:[{id:proof.actorId,skill:proof.skill,result:proof.result,side:'A'}];
 return sides.filter(x=>x.result?.level==='CF'&&!x.result?.forcedCF&&criticalActivities(x.skill).length&&
  !data.journal.some(j=>j.skillTestProof?.type==='critical-followup'&&j.skillTestProof.originId===originalId&&j.skillTestProof.side===x.side)).map(x=>{
  const options=criticalActivities(x.skill).map(a=>'<option value="'+esc(a.id)+'">'+esc(a.label)+' · HMK str. '+a.page+'</option>').join('');
  return '<form class="hsk-critical-next" data-skill-critical-form><input type="hidden" name="origin" value="'+esc(originalId)+'"><input type="hidden" name="side" value="'+x.side+'"><h4>Kritický neúspěch · '+esc(x.skill)+' · '+esc(x.side)+'</h4><p>Vyberte skutečně prováděnou činnost. Pravidlový následek nelze určit pouze podle názvu dovednosti.</p><label>Konkrétní činnost<select name="activity" required><option value="">— vyberte skutečnou činnost —</option>'+options+'</select></label><p class="hsk-followup-guidance" aria-live="polite"></p><label data-hsk-critical-technique hidden>Testovat pomocí<select name="technique" required></select><small class="hsk-critical-technique-note" aria-live="polite"></small></label><label>Pokračovací d100 (prázdné = automatický hod)<input type="number" min="1" max="100" step="1" name="followRoll"></label><button type="submit">Vyhodnotit pravidlový následek CF</button><output class="hsk-followup-output" role="status"></output></form>';
 }).join('');
}
